package org.apache.commons.cli;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;
import java.util.Properties;
import java.util.function.Supplier;

public class CommandLineTest {

    @Test
    public void testBuilder() {
        CommandLine.Builder builder = CommandLine.builder();
        assertNotNull(builder);
        assertEquals(0, builder.get().getArgs().length);
        assertEquals(0, builder.get().getOptions().length);
    }

    @Test
    public void testAddArg() {
        CommandLine.Builder builder = CommandLine.builder();
        builder.addArg("arg1");
        builder.addArg("arg2");
        CommandLine commandLine = builder.get();
        assertEquals(2, commandLine.getArgs().length);
        assertEquals("arg1", commandLine.getArgs()[0]);
        assertEquals("arg2", commandLine.getArgs()[1]);
    }

    @Test
    public void testAddOption() {
        Option option = new Option("o", "option", false, "description");
        CommandLine.Builder builder = CommandLine.builder();
        builder.addOption(option);
        CommandLine commandLine = builder.get();
        assertEquals(1, commandLine.getOptions().length);
        assertEquals(option, commandLine.getOptions()[0]);
    }

    @Test
    public void testHasOption() {
        Option option = new Option("o", "option", false, "description");
        CommandLine.Builder builder = CommandLine.builder();
        builder.addOption(option);
