package org.apache.commons.cli;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.apache.commons.cli.Option.UNINITIALIZED;
import static org.apache.commons.cli.Option.UNLIMITED_VALUES;

public class OptionTest {

    @Test
    public void testBuilderCreation() {
        Option option = Option.builder("a").build();
        assertEquals("a", option.getOpt());
        assertFalse(option.hasLongOpt());
        assertFalse(option.hasArg());
        assertFalse(option.isRequired());
    }

    @Test
    public void testBuilderWithLongOpt() {
        Option option = Option.builder("a").longOpt("arg-name").build();
        assertEquals("a", option.getOpt());
        assertEquals("arg-name", option.getLongOpt());
    }

    @Test
    public void testBuilderWithDescription() {
        Option option = Option.builder("a").desc("description").build();
        assertEquals("description", option.getDescription());
    }

    @Test
    public void testBuilderWithRequiredArg() {
        Option option = Option.builder("a").hasArg().build();
        assertTrue(option.hasArg());
        assertEquals(1, option.getArgs());
    }

    @Test
    public void testBuilderWithUnlimitedArgs() {
        Option option = Option.builder("a").hasArgs().build();
        assertTrue(option.hasArgs());
        assertEquals(UNLIMITED_VALUES, option.getArgs());
    }

    @Test
    public void testBuilderWithOptionalArg() {
        Option option = Option.builder("a").optionalArg(true).build();
        assertTrue(option.hasOptionalArg());
    }

    @Test
    public void testBuilderWithType() {
        Option option = Option.builder("a").type(Integer.class).build();
        assertEquals(Integer.class, option.getType());
    }

    @Test
    public void testBuilderWithValueSeparator() {
        Option option = Option.builder("a").valueSeparator('=').build();
        assertEquals('=', option.getValueSeparator());
        assertTrue(option.hasValueSeparator());
    }

    @Test
    public void testBuilderWithDeprecated() {
        Option option = Option.builder("a").deprecated().build();
        assertTrue(option.isDeprecated());
    }

    @Test
    public void testBuilderWithSince() {
        Option option = Option.builder("a").since("1.0").build();
        assertEquals("1.0", option.getSince());
    }

    @Test
    public void testBuilderWithArgName() {
        Option option = Option.builder("a").argName("argument-name").build();
        assertEquals("argument-name", option.getArgName());
        assertTrue(option.hasArgName());
    }

    @Test
    public void testBuilderWithNumberOfArgs() {
        Option option = Option.builder("a").numberOfArgs(3).build();
        assertEquals(3, option.getArgs());
    }

    @Test(expected = IllegalStateException.class)
    public void testBuilderWithoutOptOrLongOpt() {
        Option.builder().build();
    }

    @Test
    public void testConstructorWithShortOptAndDescription() {
        Option option = new Option("a", "description");
        assertEquals("a", option.getOpt());
        assertFalse(option.hasLongOpt());
        assertFalse(option.hasArg());
        assertFalse(option.isRequired());
    }

    @Test
    public void testConstructorWithShortOptHasArgAndDescription() {
        Option option = new Option("a", true, "description");
        assertEquals("a", option.getOpt());
        assertFalse(option.hasLongOpt());
        assertTrue(option.hasArg());
        assertFalse(option.isRequired());
    }

    @Test
    public void testConstructorWithShortOptLongOptHasArgAndDescription() {
        Option option = new Option("a", "arg-name", true, "description");
        assertEquals("a", option.getOpt());
        assertEquals("arg-name", option.getLongOpt());
        assertTrue(option.hasArg());
        assertFalse(option.isRequired());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorWithInvalidShortOpt() {
        new Option("a!", "description");
    }

    @Test
    public void testGetters() {
        Option option = Option.builder("a")
                .longOpt("arg-name")
                .desc("description")
                .hasArg()
                .required()
                .type(Integer.class)
                .valueSeparator('=')
                .deprecated()
                .since("1.0")
                .argName("argument-name")
                .numberOfArgs(2)
                .build();

        assertEquals("a", option.getOpt());
        assertEquals("arg-name", option.getLongOpt());
        assertEquals("description", option.getDescription());
        assertTrue(option.hasArg());
        assertTrue(option.isRequired());
        assertEquals(Integer.class, option.getType());
        assertEquals('=', option.getValueSeparator());
        assertTrue(option.isDeprecated());
        assertEquals("1.0", option.getSince());
        assertEquals("argument-name", option.getArgName());
        assertEquals(2, option.getArgs());
    }

    @Test
    public void testEqualsAndHashCode() {
        Option option1 = Option.builder("a").longOpt("arg-name").build();
        Option option2 = Option.builder("a").longOpt("arg-name").build();
        Option option3 = Option.builder("b").longOpt("arg-name").build();

        assertEquals(option1, option2);
        assertNotEquals(option1, option3);
        assertEquals(option1.hashCode(), option2.hashCode());
        assertNotEquals(option1.hashCode(), option3.hashCode());
    }

    @Test
    public void testToString() {
        Option option = Option.builder("a")
                .longOpt("arg-name")
                .desc("description")
                .hasArg()
                .build();

        String expected = "[ Option a arg-name [ARG] :: description :: class java.lang.String ]";
        assertEquals(expected, option.toString());
    }

    @Test
    public void testToDeprecatedString() {
        Option option = Option.builder("a")
                .deprecated()
                .since("1.0")
                .build();

        String expected = "Option 'a': Deprecated since 1.0";
        assertEquals(expected, option.toDeprecatedString());
    }

    @Test
    public void testProcessValue() {
        Option option = Option.builder("a").hasArg().build();
        option.processValue("value");
        assertEquals("value", option.getValue());
        assertEquals(1, option.getValuesList().size());
    }

    @Test
    public void testProcessValueWithSeparator() {
        Option option = Option.builder("a").hasArg().valueSeparator('=').build();
        option.processValue("key=value");
        assertEquals("key", option.getValue());
        assertEquals(1, option.getValuesList().size());
    }

    @Test(expected = IllegalStateException.class)
    public void testProcessValueWithoutArg() {
        Option option = Option.builder("a").build();
        option.processValue("value");
    }

    @Test
    public void testGetValues() {
        Option option = Option.builder("a").hasArgs().build();
        option.processValue("value1");
        option.processValue("value2");
        assertArrayEquals(new String[]{"value1", "value2"}, option.getValues());
    }

    @Test
    public void testGetValueWithIndex() {
        Option option = Option.builder("a").hasArgs().build();
        option.processValue("value1");
        option.processValue("value2");
        assertEquals("value2", option.getValue(1));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testGetValueWithInvalidIndex() {
        Option option = Option.builder("a").hasArgs().build();
        option.processValue("value1");
        option.getValue(1);
    }

    @Test
    public void testGetValueWithDefault() {
        Option option = Option.builder("a").build();
        assertEquals("default", option.getValue("default"));
    }

    @Test
    public void testClearValues() {
        Option option = Option.builder("a").hasArgs().build();
        option.processValue("value1");
        option.processValue("value2");
        option.clearValues();
        assertTrue(option.isValuesEmpty());
    }

    @Test
    public void testClone() {
        Option original = Option.builder("a").hasArg().build();
        original.processValue("value");

        Option clone = (Option) original.clone();
        assertEquals(original.getOpt(), clone.getOpt());
        assertEquals(original.getValue(), clone.getValue());
        assertNotSame(original.getValuesList(), clone.getValuesList());
    }

    @Test
    public void testAcceptsArg() {
        Option option = Option.builder("a").hasArg().build();
        assertTrue(option.acceptsArg());
        option.processValue("value");
        assertFalse(option.acceptsArg());
    }

    @Test
    public void testRequiresArg() {
        Option option = Option.builder("a").hasArg().build();
        assertTrue(option.requiresArg());
        option.processValue("value");
        assertFalse(option.requiresArg());
    }

    @Test
    public void testOptionalArg() {
        Option option = Option.builder("a").hasArg().optionalArg(true).build();
        assertTrue(option.hasOptionalArg());
        assertFalse(option.requiresArg());
    }
}

