import org.junit.Test;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class OptionFormatterTest {

    @Test
    public void testBuilderDefaultValues() {
        OptionFormatter.Builder builder = OptionFormatter.builder();
        OptionFormatter formatter = builder.build(mock(Option.class));

        assertEquals(OptionFormatter.DEFAULT_ARG_NAME_DELIMITERS[0], formatter.argNameDelimiters[0]);
        assertEquals(OptionFormatter.DEFAULT_ARG_NAME_DELIMITERS[1], formatter.argNameDelimiters[1]);
        assertEquals(OptionFormatter.DEFAULT_ARG_NAME, formatter.defaultArgName);
        assertEquals(OptionFormatter.DEFAULT_OPT_PREFIX, formatter.optPrefix);
        assertEquals(OptionFormatter.DEFAULT_LONG_OPT_PREFIX, formatter.longOptPrefix);
        assertEquals(OptionFormatter.DEFAULT_OPT_SEPARATOR, formatter.optSeparator);
        assertEquals(OptionFormatter.DEFAULT_OPT_ARG_SEPARATOR, formatter.optArgSeparator);
        assertEquals(OptionFormatter.DEFAULT_OPTIONAL_DELIMITERS[0], formatter.optionalDelimiters[0]);
        assertEquals(OptionFormatter.DEFAULT_OPTIONAL_DELIMITERS[1], formatter.optionalDelimiters[1]);
        assertEquals(OptionFormatter.NO_DEPRECATED_FORMAT, formatter.deprecatedFormatFunction);
    }

    @Test
    public void testBuilderCustomValues() {
        OptionFormatter.Builder builder = OptionFormatter.builder()
            .setArgumentNameDelimiters("(", ")")
            .setDefaultArgName("value")
            .setOptPrefix("+")
            .setLongOptPrefix("++")
            .setOptSeparator(";")
            .setOptArgSeparator("=")
            .setOptionalDelimiters("{", "}")
            .setDeprecatedFormatFunction(OptionFormatter.SIMPLE_DEPRECATED_FORMAT);

        OptionFormatter formatter = builder.build(mock(Option.class));

        assertEquals("(", formatter.argNameDelimiters[0]);
        assertEquals(")", formatter.argNameDelimiters[1]);
        assertEquals("value", formatter.defaultArgName);
        assertEquals("+", formatter.optPrefix);
        assertEquals("++", formatter.longOptPrefix);
        assertEquals(";", formatter.optSeparator);
        assertEquals("=", formatter.optArgSeparator);
        assertEquals("{", formatter.optionalDelimiters[0]);
        assertEquals("}", formatter.optionalDelimiters[1]);
        assertEquals(OptionFormatter.SIMPLE_DEPRECATED_FORMAT, formatter.deprecatedFormatFunction);
    }

    @Test
    public void testGetOpt() {
        Option option = mock(Option.class);
        when(option.getOpt()).thenReturn("x");
        OptionFormatter formatter = OptionFormatter.from(option);

        assertEquals("-x", formatter.getOpt());
    }

    @Test
    public void testGetOptEmpty() {
        Option option = mock(Option.class);
        when(option.getOpt()).thenReturn("");
        OptionFormatter formatter = OptionFormatter.from(option);

        assertEquals("", formatter.getOpt());
