package org.apache.commons.cli.help;

import org.junit.Test;
import static org.junit.Assert.*;

public class TextStyleTest {

    @Test
    public void testBuilderDefaults() {
        TextStyle style = TextStyle.builder().get();
        assertEquals(TextStyle.Alignment.LEFT, style.getAlignment());
        assertEquals(0, style.getLeftPad());
        assertEquals(0, style.getIndent());
        assertTrue(style.isScalable());
        assertEquals(0, style.getMinWidth());
        assertEquals(TextStyle.UNSET_MAX_WIDTH, style.getMaxWidth());
    }

    @Test
    public void testBuilderCustomValues() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setLeftPad(2)
                .setIndent(3)
                .setScalable(false)
                .setMinWidth(10)
                .setMaxWidth(20)
                .get();

        assertEquals(TextStyle.Alignment.RIGHT, style.getAlignment());
        assertEquals(2, style.getLeftPad());
        assertEquals(3, style.getIndent());
        assertFalse(style.isScalable());
        assertEquals(10, style.getMinWidth());
        assertEquals(20, style.getMaxWidth());
    }

    @Test
    public void testBuilderSetTextStyle() {
        TextStyle original = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.CENTER)
                .setLeftPad(5)
                .setIndent(4)
                .setScalable(true)
                .setMinWidth(15)
                .setMaxWidth(25)
                .get();

        TextStyle style = TextStyle.builder()
                .setTextStyle(original)
                .get();

        assertEquals(original.getAlignment(), style.getAlignment());
        assertEquals(original.getLeftPad(), style.getLeftPad());
        assertEquals(original.getIndent(), style.getIndent());
        assertEquals(original.isScalable(), style.isScalable());
        assertEquals(original.getMinWidth(), style.getMinWidth());
        assertEquals(original.getMaxWidth(), style.getMaxWidth());
    }

    @Test
    public void testPadLeftAlignment() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setMaxWidth(10)
                .get();

        assertEquals("hello   ", style.pad(false, "hello"));
        assertEquals("hello", style.pad(false, "hello world"));
        assertEquals("   hello", style.pad(true, "hello"));
    }

    @Test
    public void testPadRightAlignment() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.RIGHT)
                .setMaxWidth(10)
                .get();

        assertEquals("   hello", style.pad(false, "hello"));
        assertEquals("hello", style.pad(false, "hello world"));
        assertEquals("hello   ", style.pad(true, "hello"));
    }

    @Test
    public void testPadCenterAlignment() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.CENTER)
                .setMaxWidth(10)
                .get();

        assertEquals("  hello  ", style.pad(false, "hello"));
        assertEquals("hello", style.pad(false, "hello world"));
        assertEquals("  hello  ", style.pad(true, "hello"));
    }

    @Test
    public void testPadUnsetMaxWidth() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .get();

        assertEquals("hello", style.pad(false, "hello"));
        assertEquals("   hello", style.pad(true, "hello"));
    }

    @Test
    public void testToString() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.CENTER)
                .setLeftPad(2)
                .setIndent(3)
                .setScalable(false)
                .setMinWidth(10)
                .setMaxWidth(20)
                .get();

        assertEquals("TextStyle{CENTER, l:2, i:3, false, min:10, max:20}", style.toString());
    }

    @Test
    public void testToStringUnsetMaxWidth() {
        TextStyle style = TextStyle.builder()
                .setAlignment(TextStyle.Alignment.LEFT)
                .setLeftPad(0)
                .setIndent(0)
                .setScalable(true)
                .setMinWidth(0)
                .get();

        assertEquals("TextStyle{LEFT, l:0, i:0, true, min:0, max:unset}", style.toString());
    }
}

